def semver_sort(versions):
    def parse(v):
        # split off build metadata
        main_part = v
        if '+' in main_part:
            main_part = main_part.split('+', 1)[0]
        # split off pre-release
        if '-' in main_part:
            core, pre = main_part.split('-', 1)
        else:
            core, pre = main_part, None
        major, minor, patch = (int(x) for x in core.split('.'))
        if pre is None:
            has_pre = 1
            pre_key = ()
        else:
            has_pre = 0
            idents = pre.split('.')
            pre_key = tuple(
                (0, int(ident)) if ident.isdigit() else (1, ident)
                for ident in idents
            )
        return (major, minor, patch, has_pre, pre_key)

    return sorted(versions, key=parse)

